Load Custom Functions
This is just a workaround to show what I mean.

library(checkmate)
library(htmlwidgets)

add_tooltip &lt;- function(map, layer_id, lookup) {
  assert_class(map, "maplibregl")
  assert_string(layer_id)
  assert_atomic_vector(lookup)

  map |&gt;
    onRender(
      "
      function(el, x, data) {
        const map = el.map || this;
        const layerId = data.layer_id;
        const lookup = data.lookup || {};

        if (!map || typeof map.on !== 'function') {
          return;
        }

        const popup = new maplibregl.Popup({
          closeButton: false,
          closeOnClick: false,
          maxWidth: '400px'
      });

      function resolveId(props) {
        if (!props) return null;

        const candidates = [
          props.id,
          props.ID
        ];

        for (const value of candidates) {
          if (value !== undefined && value !== null) {
            const key = String(value);
            if (lookup[key] !== undefined) return key;
          }
        }

        for (const value of Object.values(props)) {
          if (value === undefined || value === null) continue;
          const key = String(value);
          if (lookup[key] !== undefined) return key;
        }

        return null;
      }

      function onMove(e) {
        if (!map.getLayer(layerId)) return;

        const features = map.queryRenderedFeatures(e.point, { layers: [layerId] });
        if (!features || features.length === 0) {
          map.getCanvas().style.cursor = '';
          popup.remove();
          return;
        }

        const props = features[0].properties || {};
        const id = resolveId(props);
        const html = id ? lookup[id] : 'No data';

        map.getCanvas().style.cursor = 'pointer';
        popup.setLngLat(e.lngLat).setHTML(html).addTo(map);
      }

      function onLeave() {
        map.getCanvas().style.cursor = '';
        popup.remove();
      }

      map.on('mousemove', onMove);
      map.on('mouseout', onLeave);
    }
    ",
      data = list(
        layer_id = layer_id,
        lookup = lookup
      )
    )
}



Set PMTiles Source

pmtiles_file &lt;- file.path(
  "https://tiles.pmtiles.com.br",
  "geobr",
  "read_state",
  paste0(
    # fmt: skip
    paste(
      "code", "all",
      "year", 2020,
      "simplified", TRUE,
      "min_zoom", 2,
      "max_zoom", 10,
      sep = "-"
    ),
    ".pmtiles"
  )
)


pmtiles_layer &lt;-
  pmtiles_file |&gt;
  pm_show(tilejson = TRUE) |&gt;
  pluck("vector_layers", 1, "id")


pmtiles_bounds &lt;-
  pmtiles_file |&gt;
  pm_show(tilejson = TRUE) |&gt;
  pluck("bounds") |&gt;
  unlist()
